<?php if(!defined('APP_ENTRY'))exit;if($_SERVER['REQUEST_METHOD']!=='GET')deny();
$data=rows('SELECT s.name,c.class_name,t.academic_year,t.semester,c.units,g.prelim,g.midterm,g.finals,g.overall,g.legacy_score,g.period_count,g.locked_count FROM grade_summary g JOIN enrollments e ON e.id=g.enrollment_id JOIN students s ON s.id=e.student_id JOIN classes c ON c.id=e.class_id JOIN academic_terms t ON t.id=c.term_id ORDER BY c.class_name,s.name');
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="grades.csv"');$f=fopen('php://output','w');fputcsv($f,['Student','Class','Academic year','Semester','Units','Prelim','Midterm','Finals','Overall','Legacy overall','Periods recorded','Periods locked'],',','"','');foreach($data as $r){$safe=array_map(fn($v)=>preg_match('/^[=+\-@\t\r\n]/',(string)$v)?"'".$v:$v,array_values($r));fputcsv($f,$safe,',','"','');}fclose($f);exit;
